/* ---------------------------- estado y persistencia ---------------------------- */
let DATA = null;
let CURRENT = 'inicio';
let SIDEBAR_COLLAPSED = false;

function loadData() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    DATA = raw ? JSON.parse(raw) : seedData();
  } catch (e) { DATA = seedData(); }
  if (!DATA) DATA = seedData();
  if (!DATA.datosFacturacion) DATA.datosFacturacion = seedData().datosFacturacion;
}
function saveData() { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(DATA)); } catch (e) {} }
function resetData() { DATA = seedData(); saveData(); render(); toast('Datos de prueba restablecidos'); }

function toast(text, esError) {
  const el = document.createElement('div');
  el.className = 'toast-item';
  el.innerHTML = (esError ? '⚠️ ' : '✅ ') + esc(text);
  document.getElementById('toast-cnt-box').appendChild(el);
  setTimeout(() => el.remove(), 3200);
}

/** Calcula el estado visual de una lección: completada, en curso, pendiente (siguiente
 *  disponible) o bloqueada (requiere completar una anterior). */
function estadoLeccion(curso, leccion) {
  const progreso = DATA.progresoLeccion[leccion.id];
  if (progreso && progreso.estado === 'completada') return { estado:'completada', fecha:progreso.fecha };
  if (progreso && progreso.estado === 'en_progreso') return { estado:'en_progreso', avance:progreso.avance||0 };
  const activas = curso.lecciones.map(id => DATA.leccionesById[id]).filter(l => l.estado === 'activa').sort((a,b)=>a.orden-b.orden);
  const idxEnProgreso = activas.findIndex(l => DATA.progresoLeccion[l.id] && DATA.progresoLeccion[l.id].estado === 'en_progreso');
  let idxMaxCompletada = -1;
  activas.forEach((l,i) => { if (DATA.progresoLeccion[l.id] && DATA.progresoLeccion[l.id].estado === 'completada') idxMaxCompletada = i; });
  const miIdx = activas.findIndex(l => l.id === leccion.id);
  const refIdx = idxEnProgreso >= 0 ? idxEnProgreso : idxMaxCompletada;
  if (miIdx <= refIdx + 1) return { estado:'pendiente' };
  return { estado:'bloqueada' };
}

/* ---------------------------- pills / píldoras de estado ---------------------------- */
function pillClass(estado) {
  const verdes = ['activo','activa','completada','aprobado','emitido','revisada','Participó'];
  const ambar = ['en_progreso','borrador','entregada','pendiente'];
  const bloqueada = ['bloqueada'];
  const azul = ['programado','programada'];
  const rojo = ['en_curso','rechazado','Sin participar'];
  const gris = ['finalizado','finalizada'];
  if (verdes.includes(estado)) return 'pill-verde';
  if (ambar.includes(estado)) return 'pill-ambar';
  if (azul.includes(estado)) return 'pill-azul';
  if (rojo.includes(estado)) return 'pill-clay';
  if (gris.includes(estado) || bloqueada.includes(estado)) return 'pill-gris';
  return 'pill-gris';
}
